-- ============================================================
-- SEED EXT 6: Módulo 05 — Future Simple (ex 204-300)
-- Tópicos: previsões baseadas em evidência, compromissos formais,
-- will vs going to, future continuous/perfect, TOEFL integrado
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'future-simple';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo future-simple não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: Will para previsões baseadas em evidência
  (cid,71,204,'gap_fill','Based on _____ (the) _____ trajectory of _____ (the) _____ past _____ decade, _____ analysts _____ (predict) that _____ renewable _____ energy _____ (account) for _____ more than _____ half of _____ global _____ electricity _____ generation within _____ fifteen _____ years.','the / trajectory / the / past / decade / predict / renewable / energy / will account / more / half / global / electricity / generation / within / fifteen / years',NULL,'''Will account for'' = prediction based on evident trajectory.','medium'),
  (cid,71,205,'gap_fill','If _____ (the) _____ current _____ rate of _____ deforestation _____ (continue), _____ remaining _____ primary _____ forest _____ in _____ (the) _____ region _____ (disappear) within _____ (a) _____ generation — _____ (a) _____ loss that _____ (prove) _____ irreversible on _____ any _____ meaningful _____ timescale.','the / current / rate / deforestation / continues / the / remaining / primary / forest / will disappear / a / a / loss / will prove / irreversible / any / meaningful',NULL,'''Will disappear/prove'' in evidence-based prediction with conditional.','medium'),
  (cid,71,206,'gap_fill','Demographic _____ projections _____ (suggest) that _____ (the) _____ global _____ population _____ (peak) at _____ approximately _____ ten _____ billion _____ by _____ mid-century before _____ (begin) to _____ decline — _____ (a) _____ shift that _____ (have) _____ profound _____ implications for _____ economic _____ planning.','projections / suggest / the / global / population / will peak / approximately / ten / billion / mid-century / beginning / decline / a / will have / profound / implications / economic / planning',NULL,'''Will peak/have'' in UN-style demographic projection.','medium'),
  (cid,71,207,'gap_fill','_____ (the) _____ technology _____ (mature) and _____ (its) _____ costs _____ (fall) further, _____ adoption _____ (accelerate) across _____ sectors that _____ (currently) _____ (face) _____ barriers that _____ (make) _____ deployment _____ economically _____ impractical.','As / technology / matures / its / costs / fall / adoption / will accelerate / across / sectors / currently / face / barriers / make / deployment / economically / impractical',NULL,'''Will accelerate'' as inevitable consequence of cost reduction in evidence-based prediction.','medium'),
  (cid,71,208,'gap_fill','Without _____ (a) _____ significant _____ change in _____ policy _____ direction, _____ (the) _____ debt _____ trajectory _____ (continue) on _____ (a) _____ path that _____ (ultimately/prove) _____ unsustainable — _____ (a) _____ scenario that _____ fiscal _____ authorities _____ (need) to _____ address _____ (before) _____ (it) _____ (no longer/passive/manage).','a / significant / change / policy / the / debt / trajectory / will continue / a / will ultimately prove / unsustainable / a / fiscal / authorities / will need / before / it / can no longer be managed',NULL,'''Will continue/prove/need'' for fiscal trajectory warning.','hard'),
  (cid,71,209,'gap_fill','_____ (the/evidence) _____ (not/any/suggest) linear _____ (progression) — _____ (there) _____ (likely/be) _____ setbacks, _____ (regression), and _____ (unforeseen) _____ developments that _____ (complicate) _____ projections. _____ (what) _____ (clear/be) is that _____ (the) _____ overall _____ direction _____ (not/reverse/passive) without _____ fundamental _____ changes.','The / evidence / does not suggest / any / linear / progression / there / will likely be / setbacks / regressions / unforeseen / will complicate / projections / What / is clear / the / overall / direction / will not be reversed / without / fundamental / changes',NULL,'''Will be/complicate/not be reversed'' in nuanced future prediction with caveats.','hard'),
  (cid,71,210,'multiple_choice','Which future form MOST APPROPRIATELY expresses a prediction based on current evidence?','Based on current trends, the urban population will exceed 70% of the global total by 2050.','[''Based on current trends, the urban population might exceed 70% by 2050.'',''Based on current trends, the urban population will exceed 70% of the global total by 2050.'',''Based on current trends, the urban population is exceeding 70% by 2050.'',''Based on current trends, the urban population would exceed 70% by 2050.'']','''Will exceed'' = confident evidence-based prediction; ''might'' = weaker uncertainty; ''is exceeding'' = present action; ''would'' = hypothetical.','easy'),
  (cid,71,211,'gap_fill','Unless _____ significant _____ structural _____ reforms _____ (implement/passive) within _____ (the) _____ next _____ electoral _____ cycle, _____ current _____ approach _____ (continue) to _____ generate _____ outcomes _____ that _____ (neither/serve) _____ efficiency _____ nor _____ equity objectives.','significant / structural / are implemented / the / next / electoral / the / current / approach / will continue / generate / outcomes / will serve neither / efficiency / equity',NULL,'''Will continue/will serve neither'' in unless-conditional reform warning.','medium'),
  (cid,71,212,'gap_fill','_____ combination of _____ (an) _____ ageing _____ population, _____ declining _____ birth _____ rates, and _____ (restrict) _____ immigration _____ policies _____ (mean) that _____ (the) _____ labor _____ force _____ (shrink) significantly over _____ (the) _____ coming _____ decades — _____ (create) _____ fiscal _____ pressures that _____ (stress) _____ existing _____ social _____ protection _____ systems.','The / combination / an / ageing / population / declining / birth / rates / restrictive / immigration / policies / means / the / labor / force / will shrink / the / coming / decades / creating / fiscal / pressures / that / will stress / existing / social / protection',NULL,'''Will shrink/stress'' for demographic-driven fiscal prediction.','hard'),

  -- BLOCK 72: Will para compromissos formais e promessas
  (cid,72,213,'gap_fill','_____ (the/government) _____ hereby _____ (commit) to _____ (reduce) _____ (its) _____ net _____ emissions by _____ forty-five _____ percent _____ by _____ 2035 and _____ (achieve) _____ net-zero _____ by _____ 2050, _____ (with) _____ progress _____ (report) _____ (annually) to _____ parliament.','The / government / hereby / commits / reduce / its / net / emissions / forty-five / percent / achieve / net-zero / with / progress / reported / annually / to',NULL,'''Commits to reduce/achieve'' = formal government pledge; ''reported'' = passive participle for annual reporting requirement.','medium'),
  (cid,72,214,'gap_fill','_____ (the/secretariat) _____ (confirm) that _____ all _____ member _____ states _____ (receive) _____ (the/final) _____ text of _____ (the) _____ agreement no _____ later _____ than _____ seventy-two _____ hours _____ before _____ (the) _____ scheduled _____ vote.','The / secretariat / confirms / all / member / states / will receive / the / final / text / the / agreement / later / than / seventy-two / hours / before / the / scheduled / vote',NULL,'''Will receive'' = formal institutional commitment to process timeline.','medium'),
  (cid,72,215,'gap_fill','_____ (the/parties) _____ hereby _____ (agree) that _____ any _____ (dispute) _____ (arise) _____ under _____ (this) _____ agreement _____ (refer/passive) to _____ binding _____ arbitration and _____ that _____ (the) _____ arbitral _____ award _____ (final/be) and _____ binding _____ on _____ both _____ parties.','The / parties / hereby / agree / that / any / disputes / arising / under / this / agreement / will be referred / binding / arbitration / that / the / arbitral / award / will be final / binding / both / parties',NULL,'''Will be referred/will be final'' in contract dispute resolution clause.','medium'),
  (cid,72,216,'gap_fill','_____ institution _____ (pledge) to _____ (report) _____ (its) _____ findings _____ publicly within _____ thirty _____ days of _____ (completing) _____ (the) _____ review and _____ (make) _____ all _____ (support) _____ data _____ available _____ to _____ (independent) _____ researchers upon _____ request.','The / pledges / report / its / findings / publicly / completing / the / review / will make / all / supporting / data / available / independent / researchers',NULL,'''Pledges to report/will make available'' for institutional transparency commitment.','medium'),
  (cid,72,217,'gap_fill','_____ donor _____ (confirm) that _____ (the/allocation) _____ _____ (disburse/passive) in _____ (three) _____ (tranche) upon _____ (demonstrate/passive) _____ compliance with _____ (the) _____ agreed _____ fiduciary _____ standards, and that _____ (no) _____ funds _____ (release/passive) without _____ prior _____ written _____ (authorization).','The / donor / confirms / the / allocation / will be disbursed / three / tranches / upon demonstrated / compliance / the / agreed / fiduciary / no / funds / will be released / without / prior / written / authorization',NULL,'''Will be disbursed/released'' in formal donor conditionality commitment.','hard'),
  (cid,72,218,'multiple_choice','Which use of ''will'' MOST NATURALLY expresses a formal written commitment?','The organization will publish the findings no later than 90 days after the conclusion of the study.','[''The organization is going to publish the findings.'',''The organization may publish the findings.'',''The organization will publish the findings no later than 90 days after the conclusion of the study.'',''The organization shall be publishing the findings.'']','''Will publish'' in formal commitments is standard; ''going to'' is informal; ''shall be publishing'' is unusual; ''may'' = permission.','easy'),
  (cid,72,219,'gap_fill','_____ (the/company) _____ (undertake) to _____ (maintain) _____ confidentiality of _____ all _____ (client) _____ information _____ (receive/passive) in _____ (the) _____ course of _____ (the) _____ engagement and _____ (not/disclose) such _____ information to _____ (any/third/party) without _____ (the) _____ client''s _____ prior _____ written _____ consent.','The / company / undertakes / maintain / the / confidentiality / all / client / information / received / the / course / the / engagement / will not disclose / such / information / any third party / without / the / prior / written',NULL,'''Undertakes to maintain/will not disclose'' in confidentiality undertaking.','medium'),
  (cid,72,220,'gap_fill','_____ (the/board) _____ (resolve) that _____ management _____ (take) _____ all _____ necessary _____ steps to _____ (ensure) that _____ (the) _____ (identify/passive) _____ deficiencies _____ (rectify/passive) within _____ sixty _____ days and _____ that _____ (a) _____ comprehensive _____ remediation _____ plan _____ (present/passive) at _____ (the) _____ next _____ board _____ meeting.','The / board / resolves / that / management / will take / all / necessary / steps / ensure / the / identified / deficiencies / will be rectified / sixty / days / that / a / comprehensive / remediation / plan / will be presented / the / next / board / meeting',NULL,'''Will take/be rectified/be presented'' in board resolution formal language.','hard'),

  -- BLOCK 73: Going to para intenções planejadas formais
  (cid,73,221,'gap_fill','_____ (the/minister) _____ (announce) yesterday that _____ (the) _____ government _____ (overhaul) _____ (the) _____ tax _____ code completely, _____ (introduce) _____ simplified _____ (structure) that _____ (reduce) _____ compliance _____ costs for _____ small _____ businesses.','The / minister / announced / the / government / was going to overhaul / the / tax / code / completely / introducing / a / simplified / structure / would reduce / compliance / costs / small / businesses',NULL,'''Was going to overhaul'' = announced plan in past narrative; ''would reduce'' = future in the past.','hard'),
  (cid,73,222,'gap_fill','We _____ (not/implement) _____ (this) _____ without _____ (first) _____ (consult) _____ all _____ (the) _____ affected _____ stakeholders — that _____ (be) _____ a _____ non-negotiable _____ requirement _____ of _____ (the) _____ process _____ as _____ we _____ (conceive) it.','are not going to implement / this / without / first / consulting / all / the / affected / stakeholders / that / is / a / non-negotiable / requirement / the / process / we / have conceived',NULL,'''Are not going to implement'' = planned prohibition; ''is'' = categorical statement.','medium'),
  (cid,73,223,'gap_fill','_____ (the/organization) _____ (launch) _____ (its) _____ new _____ strategic _____ framework next _____ quarter — _____ (the/leadership) _____ (brief) _____ (the) _____ board on _____ (the) _____ details _____ next _____ week before _____ (the) _____ public _____ announcement.','The / organization / is going to launch / its / new / strategic / framework / the leadership / is going to brief / the / board / the / details / next / week / before / the / public / announcement',NULL,'''Is going to launch/brief'' = arranged future plans for organizational rollout.','medium'),
  (cid,73,224,'gap_fill','Look at _____ (these) _____ indicators — _____ (the) _____ economy _____ (contract). _____ (the/central/bank) _____ (have to) _____ (respond) _____ (aggressively) or _____ (there) _____ (be) _____ (a) _____ significant _____ recession _____ by _____ (the) _____ end of _____ (the) _____ year.','these / indicators / the / economy / is going to contract / The central bank / is going to have to / respond / aggressively / there / is going to be / a / significant / recession / the / end / the / year',NULL,'''Is going to contract/is going to have to/is going to be'' for prediction based on visible evidence.','hard'),
  (cid,73,225,'gap_fill','_____ (the/program) _____ (expand) to _____ (cover) _____ three _____ additional _____ regions in _____ (the) _____ second _____ phase, _____ (reach) _____ approximately _____ (twice) _____ as _____ many _____ beneficiaries _____ as _____ (the) _____ current _____ implementation.','The / program / is going to expand / to / cover / three / additional / regions / the / second / phase / reaching / approximately / twice / as / many / beneficiaries / as / the / current',NULL,'''Is going to expand'' = announced program plan + participial ''reaching.''','medium'),
  (cid,73,226,'gap_fill','Based _____ on _____ (the) _____ preliminary _____ results, _____ it _____ (be) _____ (clear) that _____ (the) _____ initiative _____ (not/achieve) _____ (its) _____ target — _____ (the/program) _____ (need) _____ (a) _____ significant _____ redesign if _____ (it) _____ (to/deliver) _____ (the) _____ promised _____ outcomes.','on / the / preliminary / results / is / clear / the / initiative / is not going to achieve / its / target / the program / is going to need / a / significant / redesign / it / is to deliver / the / promised / outcomes',NULL,'''Is not going to achieve/is going to need'' = evidence-based negative prediction + plan requirement.','hard'),
  (cid,73,227,'multiple_choice','Which future form BEST expresses a pre-arranged institutional plan?','The committee is going to release its findings at a press conference scheduled for Thursday.','[''The committee will release its findings at a press conference scheduled for Thursday.'',''The committee is going to release its findings at a press conference scheduled for Thursday.'',''The committee releases its findings at a press conference scheduled for Thursday.'',''The committee would release its findings at a press conference scheduled for Thursday.'']','''Is going to release'' = arranged plan in progress. ''Will release'' is also correct but ''going to'' is more appropriate for already-arranged plans.','medium'),
  (cid,73,228,'gap_fill','_____ (we) _____ (not/accept) _____ (any/offer) that _____ (not/include) _____ adequate _____ protection for _____ workers _____ currently _____ (employ/passive) in _____ (the) _____ affected _____ facilities — _____ (that) _____ (be) _____ (our) _____ clear and _____ stated _____ (negotiating) _____ position.','We / are not going to accept / any offer / does not include / adequate / protection / workers / currently employed / the / affected / that / is / our / clear / stated / negotiating / position',NULL,'''Are not going to accept'' = firm announced intention; ''is'' = categorical statement of position.','medium'),

  -- BLOCK 74: Future continuous (will be doing)
  (cid,74,229,'gap_fill','By _____ (the) _____ time _____ (the) _____ new _____ administration _____ (take) _____ office, _____ implementation _____ teams _____ (already/work) _____ on _____ (the) _____ transition _____ plan that _____ (develop/passive) _____ (by) _____ (the) _____ current _____ government.','the / time / the / new / administration / takes / implementation / teams / will already be working / on / the / transition / plan / that / will have been developed / by / the / current',NULL,'''Will be working'' + ''will have been developed'' for parallel future continuous and future perfect.','hard'),
  (cid,74,230,'gap_fill','While _____ (the) _____ negotiators _____ (finalize) _____ (the) _____ text in _____ Geneva, _____ technical _____ teams _____ (work) _____ in _____ parallel to _____ (develop) _____ implementing _____ regulations that _____ (need/passive) to _____ (be) _____ ready _____ when _____ (the) _____ agreement _____ (enter) _____ into _____ force.','the / negotiators / are finalizing / the / text / technical / teams / will be working / in / parallel / develop / implementing / regulations / will need / be / ready / when / the / agreement / enters / into / force',NULL,'PC ''are finalizing'' + ''will be working'' for simultaneous future activities.','hard'),
  (cid,74,231,'gap_fill','_____ analysts _____ (closely/watch) _____ (the) _____ quarterly _____ results when _____ (they) _____ (release/passive) next week — _____ (the) _____ market _____ (look) for _____ evidence that _____ (the) _____ recovery _____ (sustain) and _____ that _____ margin _____ improvement _____ (continue).','Analysts / will be closely watching / the / quarterly / results / when / they / are released / the / market / will be looking / for / evidence / the / recovery / is being sustained / margin / improvement / is continuing',NULL,'''Will be watching/looking'' for scheduled future analyst activity around event.','medium'),
  (cid,74,232,'gap_fill','_____ (don''t) _____ (try) to _____ (reach) _____ (me) between _____ two and _____ five _____ — I _____ (present) to _____ (the) _____ board and _____ then _____ (brief) _____ (the) _____ minister and _____ (will/not/able/be) to _____ (return) _____ calls until _____ (the) _____ evening.','Don''t / try / reach / me / between / two / five / will be presenting / to / the / board / then / briefing / the / minister / will not be able / return / calls / the / evening',NULL,'''Will be presenting/briefing'' for scheduled overlapping future activities.','easy'),
  (cid,74,233,'gap_fill','_____ (the) _____ independent _____ monitor _____ (observe) _____ (the) _____ proceedings _____ and _____ (prepare) _____ (its) _____ assessment _____ throughout _____ (the) _____ review _____ period — a _____ report _____ that _____ (submit/passive) to _____ (the) _____ oversight _____ body _____ at _____ (the) _____ conclusion.','The / independent / monitor / will be observing / the / proceedings / preparing / its / assessment / throughout / the / review / period / a / report / that / will be submitted / the / oversight / body / at / the / conclusion',NULL,'''Will be observing/preparing'' for scheduled ongoing future monitoring activity.','medium'),
  (cid,74,234,'multiple_choice','Which future continuous sentence is MOST APPROPRIATE in a formal context?','The Secretary will be attending the afternoon session and will be available for bilateral meetings thereafter.','[''The Secretary attends the afternoon session and will be available for bilateral meetings.'',''The Secretary is going to attend the afternoon session and be available for bilateral meetings.'',''The Secretary will be attending the afternoon session and will be available for bilateral meetings thereafter.'',''The Secretary will attend the afternoon session and is available for bilateral meetings.'']','''Will be attending/will be available'' = formal scheduled future activities; professional diplomatic language.','easy'),
  (cid,74,235,'gap_fill','In _____ ten _____ years, _____ researchers _____ in _____ (this) _____ field _____ (work) with _____ datasets _____ and _____ tools that _____ (not/exist) _____ today — _____ (a) _____ reminder that _____ (the) _____ questions _____ we _____ (ask) now _____ (shape) _____ the _____ methods _____ (develop/passive) _____ to _____ answer them.','ten / years / researchers / in / this / field / will be working / datasets / and / tools / do not exist / a / reminder / the / questions / we / ask / now / will shape / the / methods / developed / answer',NULL,'''Will be working'' + ''do not exist/will shape'' for future research landscape prediction.','medium'),
  (cid,74,236,'gap_fill','_____ (the) _____ international _____ community _____ (watch) closely how _____ (the) _____ situation _____ (develop) over _____ (the) _____ coming _____ weeks — _____ (the) _____ response _____ or _____ lack of _____ (it) _____ (signal) _____ (the) _____ extent to _____ which _____ (the) _____ norms _____ (intend/passive) to _____ govern _____ such _____ situations _____ (actually/hold).','The / international / community / will be watching / closely / the / situation / develops / the / coming / weeks / the / response / or / lack / will signal / the / extent / to / which / the / norms / intended / govern / such / situations / actually / hold',NULL,'''Will be watching'' + ''will signal'' for ongoing future monitoring and its implications.','hard'),

  -- BLOCK 75: Future perfect (will have done)
  (cid,75,237,'gap_fill','By _____ (the) _____ time _____ (the) _____ review _____ (complete/passive), _____ (the) _____ committee _____ (examine) _____ more _____ than _____ three _____ hundred _____ (submission) and _____ (conduct) _____ hearings with _____ (over) _____ fifty _____ witnesses.','the / time / the / review / is completed / the / committee / will have examined / more / than / three / hundred / submissions / will have conducted / hearings / over / fifty / witnesses',NULL,'''Will have examined/conducted'' = future perfect for actions completed before a future point.','medium'),
  (cid,75,238,'gap_fill','By _____ mid-century, _____ investment in _____ (the) _____ technology _____ (cumulate) to _____ over _____ (a) _____ trillion _____ dollars _____ — assuming _____ (current) _____ commitments _____ (honor/passive) and _____ (the) _____ pipeline of _____ projects _____ (proceed) as _____ (plan).','mid-century / investment / the / technology / will have cumulatively reached / over / a / trillion / assuming / current / commitments / are honored / the / pipeline / projects / proceeds / as / planned',NULL,'''Will have reached'' (future perfect) for cumulative investment by future date.','hard'),
  (cid,75,239,'gap_fill','Within _____ (a) _____ decade, _____ artificial _____ intelligence _____ (transform) _____ virtually _____ every _____ sector of _____ (the) _____ economy in _____ ways that _____ we _____ (barely/begin) to _____ (anticipate) today — _____ (a) _____ transformation _____ that _____ (unfold) _____ faster than _____ any _____ previous _____ technological _____ (revolution).','a / decade / artificial / intelligence / will have transformed / virtually / every / sector / the / economy / we / have barely begun / anticipate / today / a / transformation / that / will have unfolded / faster / any / previous / technological / revolution',NULL,'''Will have transformed/unfolded'' for future perfect in technological transformation.','hard'),
  (cid,75,240,'multiple_choice','Which future perfect construction MOST CORRECTLY describes an action completed before a future point?','By the time the new facility opens, the team will have been conducting preparatory work for three years.','[''By the time the new facility opens, the team has been conducting preparatory work for three years.'',''By the time the new facility opens, the team will have been conducting preparatory work for three years.'',''By the time the new facility opens, the team will conduct preparatory work for three years.'',''By the time the new facility opens, the team had been conducting preparatory work for three years.'']','''Will have been conducting'' = future perfect continuous; emphasizes the duration of work completed before the facility opens.','medium'),
  (cid,75,241,'gap_fill','If _____ (the) _____ reforms _____ (implement/passive) on _____ schedule, _____ (the) _____ fiscal _____ position _____ (improve) substantially by _____ (the) _____ time _____ of _____ (the) _____ next _____ review — _____ (the) _____ deficit _____ (reduce) by _____ approximately _____ half and _____ (the) _____ debt-to-GDP _____ ratio _____ (begin) to _____ fall.','the / reforms / are implemented / on / the / fiscal / position / will have improved / substantially / the / time / the / next / review / the / deficit / will have reduced / approximately / half / the / debt-to-GDP / ratio / will have begun / fall',NULL,'''Will have improved/reduced/begun'' for conditional future perfect outcomes.','hard'),
  (cid,75,242,'gap_fill','Before _____ (the) _____ decade _____ (be) _____ out, _____ (the) _____ scientific _____ community _____ (accumulate) _____ sufficient _____ evidence to _____ (resolve) _____ (the) _____ key _____ empirical _____ disputes that _____ (currently) _____ (prevent) _____ (a) _____ consensus from _____ forming.','the / decade / is / out / the / scientific / community / will have accumulated / sufficient / evidence / resolve / the / key / empirical / disputes / currently / prevent / a / consensus / forming',NULL,'''Will have accumulated'' (future perfect) for evidence threshold before decade ends.','medium'),
  (cid,75,243,'gap_fill','_____ those who _____ (reach) _____ retirement age by _____ 2040, _____ (the) _____ landscape of _____ (work) _____ (change) _____ beyond _____ recognition during _____ (their) _____ working _____ lives — _____ (they) _____ (navigate) _____ multiple _____ career _____ transitions _____ (drive) by _____ technological _____ change.','For / reach / those / retirement / age / by / the / landscape / work / will have changed / beyond / recognition / their / working / lives / they / will have navigated / multiple / career / transitions / driven / technological',NULL,'''Will have changed/navigated'' for cumulative life experience by future retirement date.','hard'),
  (cid,75,244,'gap_fill','By _____ (the) _____ time _____ (the) _____ next _____ (generation) _____ (lead) _____ these _____ institutions, _____ (the) _____ decisions _____ _____ (make) today _____ (either/create) _____ conditions for _____ success or _____ (plant) _____ seeds of _____ (difficulty) that _____ (their) _____ successors _____ (inherit).','the / time / the / next / generation / comes to lead / these / institutions / the / decisions / we / make / today / will either have created / conditions / success / planted / seeds / difficulty / their / successors / will have inherited',NULL,'''Will have created/planted/inherited'' for generational future perfect consequences.','hard'),

  -- BLOCK 76: TOEFL Reading com formas futuras
  (cid,76,245,'multiple_choice','[TOEFL Reading] ''Scientists project that sea levels will rise by up to one meter by the end of the century.'' The word ''will'' in this context:','Expresses a confident prediction based on current scientific evidence.','[''Expresses a wish or desire'',''Expresses a confident prediction based on current scientific evidence.'',''Expresses a habitual action'',''Expresses a past event'']','''Will rise'' = evidence-based scientific prediction, the core use of will for future.','easy'),
  (cid,76,246,'gap_fill','[TOEFL Reading] ''The measure _____ (likely/prove) insufficient unless _____ (it) _____ (complement/passive) by _____ broader _____ structural _____ changes that _____ (address) _____ root _____ causes rather than _____ surface _____ symptoms.'' Best forms?','will likely prove / it / is complemented / broader / structural / changes / address / root / causes / surface',NULL,'''Will likely prove'' (probability-hedged prediction) + ''is complemented'' (conditional present) + ''address'' (present simple).','medium'),
  (cid,76,247,'gap_fill','[TOEFL Reading] ''By _____ (the) _____ end of _____ (the) _____ decade, _____ (the) _____ cumulative _____ effect of _____ (these) _____ investments _____ (visible/become) in _____ (the) _____ form of _____ improved _____ infrastructure, _____ stronger _____ institutions, and _____ higher _____ productivity.'' Best forms?','the / end / the / decade / the / cumulative / effect / these / investments / will have become visible / the / form / improved / infrastructure / stronger / institutions / higher / productivity',NULL,'''Will have become visible'' (future perfect) for cumulative investment effect by decade end.','medium'),
  (cid,76,248,'gap_fill','[TOEFL Reading] ''Those who _____ (resist) _____ (the) _____ change _____ (find) themselves _____ increasingly _____ (marginalize/passive) as _____ (the) _____ new _____ paradigm _____ (consolidate) and _____ (become) _____ (the) _____ new _____ orthodoxy.'' Best forms?','resist / the / will find / themselves / increasingly / marginalized / the / new / paradigm / consolidates / becomes / the / new / orthodoxy',NULL,'''Will find...marginalized'' = prediction of consequence for resisters; PS ''consolidates/becomes'' = natural process.','hard'),
  (cid,76,249,'gap_fill','[TOEFL Reading] ''The transition _____ (painful) _____ (be) for _____ (those) _____ whose _____ skills _____ (not/adequately/transfer) to _____ (the) _____ new _____ economy — _____ (a) _____ challenge that _____ policy _____ (need) to _____ address _____ (proactively) rather than _____ after _____ (the/fact).'' Best forms?','will be painful / for / those / whose / skills / do not adequately transfer / the / new / economy / a / challenge / that / policy / needs / address / proactively / the fact',NULL,'''Will be painful'' + PS ''transfer/needs'' for transition consequence and policy recommendation.','hard'),
  (cid,76,250,'multiple_choice','[TOEFL Reading] ''The author suggests that reform will require sustained political will over a period of years.'' This sentence implies:','The reform process will be challenging and cannot be completed quickly.','[''Reform is impossible'',''The author is uncertain about reform'',''The reform process will be challenging and cannot be completed quickly.'',''Reform was recently completed'']','''Will require sustained political will over years'' = prediction of a long, difficult process.','easy'),
  (cid,76,251,'gap_fill','[TOEFL Reading] ''_____ (the) _____ century _____ (progress), _____ (the) _____ relationship between _____ humans and _____ (the) _____ natural _____ world _____ (either/transform) in _____ ways that _____ (allow) _____ sustainable _____ coexistence, or _____ (the) _____ pressures _____ (build) to _____ (a) _____ point where _____ large-scale _____ ecological _____ (collapse) _____ (become) _____ (unavoidable).'' Best forms?','As / the / century / progresses / the / relationship / between / humans / the / natural / world / will either be transformed / in / ways / allow / sustainable / coexistence / the / pressures / will build / a / point / large-scale / ecological / collapse / becomes / unavoidable',NULL,'''Will be transformed/build/becomes'' for century-scale future binary outcome.','hard'),
  (cid,76,252,'gap_fill','[TOEFL Reading] ''Whether _____ (the) _____ initiative _____ (succeed) or _____ (fail) _____ (depend) on _____ (a) _____ combination of _____ factors that _____ include _____ political _____ commitment, _____ institutional _____ capacity, and _____ external _____ conditions that _____ neither _____ (party) _____ (fully/control).'' Best forms?','the / initiative / will succeed / fail / will depend / a / combination / factors / include / political / commitment / institutional / capacity / external / conditions / neither / party / fully controls',NULL,'''Will succeed/fail/depend'' + ''neither party controls'' for multi-factor future contingency.','hard'),

  -- BLOCK 77: TOEFL Speaking com formas futuras
  (cid,77,253,'production','[TOEFL Speaking — 45s] The reading predicts what will happen if automation continues at its current pace. Summarize.','',NULL,'The reading predicts that if automation continues at its current pace, the labor market will experience a significant structural transformation that will create both opportunities and serious challenges. On the positive side, the reading suggests that automation will boost productivity substantially, meaning that overall economic output will grow and that new categories of jobs will emerge in areas that require distinctly human capabilities. However, the reading warns that the transition will be painful for workers whose skills do not translate to the new economic landscape. If retraining programs and social safety nets are not significantly strengthened, the reading predicts that income inequality will widen substantially as the gains from automation will accrue primarily to capital owners and highly skilled workers, while workers in routine occupations will face wage pressure and displacement. The reading concludes that the key question is not whether automation will transform the economy — the reading predicts it will — but whether policy will ensure that the benefits are broadly shared and that displaced workers will have pathways to new employment that offer comparable wages and security to what they are currently earning.','hard'),
  (cid,77,254,'production','[TOEFL Speaking — 45s] The professor discusses what will happen to urban areas over the next 50 years.','',NULL,'The professor predicts significant changes in urban areas over the next fifty years, driven primarily by climate change, demographic shifts, and technological transformation. She argues that cities will face increasing climate-related stress: many coastal cities will need to invest heavily in adaptation infrastructure or will face growing risks of flooding and storm damage. The heat island effect will intensify in dense urban areas, requiring significant changes to building codes and urban design if cities are to remain livable in warmer conditions. Demographically, the professor predicts that cities in high-income countries will continue to age as birth rates remain low, while cities in low-income countries will continue to absorb large numbers of rural migrants, creating very different challenges in different contexts. Technologically, she argues that autonomous vehicles will transform urban transportation systems, potentially freeing up significant amounts of land currently used for parking and roads for other purposes. Smart city technologies will improve the efficiency of urban services but will also raise important questions about privacy and data governance. The professor concludes that cities that invest in adaptation now will be significantly better positioned than those that delay, and that the decisions made in the next decade will shape the urban landscape that future generations will inherit.','hard'),
  (cid,77,255,'production','[TOEFL Speaking — 60s] Compare what the reading and the professor say will happen if AI is not regulated. Use future forms throughout.','',NULL,'The reading and the professor agree that the absence of adequate regulation of artificial intelligence will lead to serious problems, but they disagree about which problems will prove most severe. The reading focuses primarily on economic impacts: it predicts that without regulation requiring fair competition, dominant AI companies will consolidate market power in ways that will reduce innovation and will extract rents from businesses and consumers who will have few alternatives. The reading also predicts that without transparency requirements, AI systems will increasingly be used to make consequential decisions — about credit, employment, healthcare, and criminal justice — in ways that will systematically disadvantage already-marginalized groups because the biases embedded in training data will be reproduced and amplified rather than corrected. The professor agrees with these concerns but argues that the most serious risks will be in the domain of security and geopolitical stability. She predicts that without international coordination on AI governance, states will deploy AI in military and intelligence applications that will accelerate the pace of conflict in dangerous ways. She also argues that without standards for critical infrastructure, AI systems will create systemic vulnerabilities that adversaries will exploit. The professor concludes that while economic regulation will be important, the most urgent need will be for international agreements that will constrain the deployment of AI in high-stakes security domains — agreements that will be very difficult to negotiate but that will become increasingly necessary as capabilities advance.','hard'),
  (cid,77,256,'gap_fill','[TOEFL Speaking] Based on _____ (the) _____ evidence _____ (present/passive) in _____ (the) _____ reading, _____ (the) _____ professor _____ (argue) that _____ (the) _____ scenario _____ most likely _____ (unfold) _____ (be) one in which _____ (the) _____ gradual _____ accumulation of _____ (small) _____ changes _____ (eventually) _____ (produce) _____ (a) _____ transformation _____ that _____ (appear) _____ sudden.','the / evidence / presented / the / reading / the / professor / argues / the / scenario / that / will most likely / unfold / is / the / gradual / accumulation / small / changes / will eventually produce / a / transformation / that / will appear / sudden',NULL,'''Will most likely unfold/produce/appear'' for probability-hedged prediction about gradual transformation.','hard'),

  -- BLOCK 78: TOEFL Writing com formas futuras
  (cid,78,257,'production','[TOEFL Writing — 200 words] Write a paragraph predicting the future of democratic governance.','',NULL,'Democratic governance will face its most significant stress test in decades over the coming years as a confluence of pressures — technological, economic, and geopolitical — simultaneously challenges the institutions and norms on which democratic systems depend. The information environment will continue to be shaped by platforms that algorithmically amplify divisive content, making it increasingly difficult to maintain the shared factual basis that democratic deliberation requires. Economic inequality will continue to generate political grievances that populist movements will exploit, channeling legitimate frustrations about distribution in directions that threaten rather than strengthen democratic institutions. Geopolitical competition will create pressure on governments to prioritize national security over civil liberties and to weaken the international norms that constrain authoritarian behavior globally. Against these headwinds, democratic systems will also demonstrate resilience: civil society will mobilize in defense of threatened institutions, judicial systems will resist executive overreach, and citizens who had been politically disengaged will re-engage when they perceive democracy itself to be at risk. The outcome will not be determined by impersonal historical forces but by the choices that leaders, institutions, and citizens will make. If those choices consistently prioritize the long-term health of democratic institutions over short-term political advantages, democratic systems will survive and adapt. If they do not, the accumulated damage will prove increasingly difficult to repair.','hard'),
  (cid,78,258,'production','[TOEFL Writing — 200 words] Write a body paragraph on what will happen if the international community fails to act on climate change.','',NULL,'If the international community fails to take the coordinated action that the scientific evidence indicates is necessary, the consequences will be severe, widespread, and increasingly irreversible. Average global temperatures will exceed the 2-degree threshold that scientists have identified as the point beyond which the risk of catastrophic and self-reinforcing feedback loops increases substantially. Extreme weather events will intensify and become more frequent, imposing growing costs on communities around the world, with the most severe impacts falling on the countries that have contributed least to the problem. Sea level rise will threaten coastal cities and low-lying nations with a combination of flooding, storm surge, and salt water intrusion into freshwater supplies that will render some areas uninhabitable within decades. Agricultural systems will face increasing disruption as rainfall patterns shift and as extreme heat events reduce yields in regions that currently feed large populations, increasing food insecurity and potentially driving large-scale migration. The economic costs will accumulate over time and will ultimately dwarf the costs of the mitigation that would have prevented them. The distributional consequences will be deeply inequitable, as the populations least responsible for causing climate change will bear the largest share of its impacts. And unlike most policy failures, which can be corrected when their costs become apparent, the feedback dynamics of the climate system mean that some of the consequences will prove irreversible on any timescale relevant to human civilization.','hard'),
  (cid,78,259,'gap_fill','[TOEFL Writing] _____ challenge _____ (not/disappear) because _____ (we) _____ choose to _____ (ignore) it — _____ indeed, _____ (delay) _____ (only/ensure) that _____ (the) _____ costs of _____ addressing _____ it _____ (higher/be) when _____ (the) _____ moment of _____ reckoning _____ (eventually/arrive).','The / challenge / will not disappear / we / ignore / delay / will only ensure / the / costs / addressing / will be higher / the / moment / reckoning / eventually arrives',NULL,'''Will not disappear/will only ensure/will be higher'' for cost-of-delay argument.','medium'),
  (cid,78,260,'gap_fill','[TOEFL Writing] _____ (the) _____ decisions _____ (make/passive) in _____ (the) _____ next _____ decade _____ (shape) _____ (the) _____ trajectory for _____ generations — _____ this is not _____ (hyperbole) but _____ (a) _____ sober _____ assessment of _____ what _____ (the) _____ evidence _____ (show).','The / decisions / made / the / next / decade / will shape / the / trajectory / generations / this / hyperbole / a / sober / assessment / what / the / evidence / shows',NULL,'''Will shape'' + PS ''shows'' for generational stakes argument.','medium'),
  (cid,78,261,'gap_fill','[TOEFL Writing] Whether _____ (this/generation) _____ (rise) to _____ (meet) _____ (the) _____ challenge _____ (determine) what _____ kind of _____ world _____ (those/come after) _____ (inherit) — _____ and _____ (they) _____ (judge) _____ (us) not by _____ (our) _____ (intentions) but by _____ (our) _____ actions.','this generation / rises / meet / the / challenge / will determine / what / kind / world / those who come after / will inherit / they / will judge / us / our / intentions / our / actions',NULL,'PS ''rises/determines/inherit'' + ''will judge'' for generational accountability argument.','hard'),
  (cid,78,262,'gap_fill','[TOEFL Writing] The future _____ (not/fixed) — _____ (there) _____ (always/be) _____ multiple _____ possible _____ trajectories, and _____ (which) of _____ them _____ (materialize) _____ (depend) on _____ choices _____ (make/passive) now by _____ individuals, _____ institutions, and _____ governments at _____ every _____ level.','is not fixed / there / will always be / multiple / possible / trajectories / which / of / them / materializes / will depend / on / choices / made / now / individuals / institutions / governments / every',NULL,'''Is not fixed/will always be/will depend'' for open future contingency argument.','medium'),

  -- BLOCK 79: Will em previsões acadêmicas
  (cid,79,263,'gap_fill','_____ (the) _____ field _____ (look) very _____ different in _____ twenty _____ years — _____ (the) _____ methods _____ currently _____ (consider/passive) _____ state-of-the-art _____ (largely/supersede/passive) by _____ approaches that _____ (not/yet/imagine/passive).','The / will look / very / different / twenty / years / the / methods / currently / considered / state-of-the-art / will largely have been superseded / approaches / have not yet been imagined',NULL,'''Will look/will have been superseded'' for disciplinary future prediction.','hard'),
  (cid,79,264,'gap_fill','Scholars _____ (continue) to _____ (debate) _____ (the) _____ question for _____ decades to _____ come — _____ (the) _____ current _____ evidence _____ (not/sufficient/be) to _____ (resolve) it definitively, and _____ (the/kind/of) _____ empirical _____ work _____ (need/passive) to _____ (do) so _____ (only/become) possible as _____ (new) _____ data _____ (become) _____ available.','will continue / debate / the / question / decades / come / the / current / evidence / will not be sufficient / resolve / it / the kind of / empirical / work / needed / do / will only become / possible / new / data / become / available',NULL,'''Will continue/not be sufficient/will only become'' for long scholarly debate prediction.','hard'),
  (cid,79,265,'gap_fill','_____ (the) _____ integration of _____ artificial _____ intelligence into _____ (the) _____ research _____ process _____ (fundamentally/alter) how _____ (the) _____ scientific _____ community _____ (generate) and _____ (evaluate) _____ knowledge — _____ (a) _____ transformation that _____ (both/challenge) existing _____ (norms) of _____ scholarly _____ practice and _____ (create) _____ (new) _____ possibilities.','The / integration / artificial / intelligence / into / the / research / process / will fundamentally alter / how / the / scientific / community / generates / evaluates / knowledge / a / transformation / will both challenge / existing / norms / scholarly / practice / will create / new / possibilities',NULL,'''Will fundamentally alter/challenge/create'' for AI impact on research process.','hard'),
  (cid,79,266,'gap_fill','Future _____ (historian) _____ (look back) on _____ (this) _____ period as _____ (a) _____ critical _____ juncture — _____ one at which _____ (the) _____ decisions _____ (make/passive) _____ (either/put) _____ humanity on _____ (a) _____ more _____ sustainable _____ path or _____ (lock it) into _____ trajectories that _____ (prove) _____ difficult to _____ alter.','Future / historians / will look back / on / this / period / as / a / critical / juncture / one / at / which / the / decisions / made / will either put / humanity / a / more / sustainable / path / will lock it / into / trajectories / will prove / difficult / alter',NULL,'''Will look back/put/lock/prove'' for historical judgment future prediction.','hard'),
  (cid,79,267,'gap_fill','_____ (the) _____ synthesis of _____ insights from _____ multiple _____ (discipline) _____ (require) _____ (a) _____ new _____ generation of _____ researchers _____ trained to _____ work _____ across _____ disciplinary _____ (boundary) — _____ (a) _____ challenge for _____ (the) _____ institutions _____ that _____ (train) them and _____ that _____ (certify) _____ expertise.','The / synthesis / insights / multiple / disciplines / will require / a / new / generation / researchers / trained / work / across / disciplinary / boundaries / a / challenge / the / institutions / train / certify / expertise',NULL,'''Will require'' for future interdisciplinary research needs.','medium'),
  (cid,79,268,'multiple_choice','Which future construction MOST EFFECTIVELY makes a hedged academic prediction?','The evidence suggests that this approach will likely prove more effective than current alternatives, though further research will be needed to confirm this.','[''The evidence suggests this approach proves more effective than current alternatives.'',''The evidence suggests that this approach will likely prove more effective than current alternatives, though further research will be needed to confirm this.'',''The evidence suggests that this approach would be more effective than current alternatives.'',''The evidence suggests that this approach will definitely prove more effective.'']','''Will likely prove'' = hedged confidence; ''though further research will be needed'' = appropriate epistemic humility.','easy'),
  (cid,79,269,'gap_fill','_____ (the) _____ questions _____ we _____ (pursue) today _____ (shape) _____ (the) _____ questions _____ that _____ (arise) tomorrow — _____ (a) _____ recursion that _____ (mean) that _____ (the) _____ choices _____ we _____ (make) about _____ what to _____ (study) and _____ how _____ (are) of _____ (consequence) _____ (extend/passive) _____ far _____ beyond _____ (the) _____ immediate _____ context.','The / questions / we / pursue / today / will shape / the / questions / that / arise / tomorrow / a / recursion / means / the / choices / we / make / study / how / are / consequence / extend / far / beyond / the / immediate / context',NULL,'''Will shape/arise'' for recursive impact of today''s research choices.','hard'),
  (cid,79,270,'gap_fill','Scholars who _____ (fail) to _____ (engage) with _____ (these) _____ methodological _____ advances _____ (find) themselves _____ (increasingly/marginalize/passive) from _____ (the) _____ mainstream of _____ (the) _____ discipline — a _____ reality that _____ (create) _____ (both) _____ opportunities and _____ pressures for _____ (those) _____ entering _____ (the) _____ field.','fail / engage / these / methodological / advances / will find / themselves / increasingly marginalized / the / mainstream / the / discipline / a / reality / creates / both / opportunities / pressures / those / entering / the / field',NULL,'''Will find...marginalized'' + PS ''creates'' for methodological adaptation prediction.','hard'),

  -- BLOCK 80: Future em frases condicionais
  (cid,80,271,'gap_fill','_____ (the) _____ investment _____ (not/generate) _____ (the) _____ returns _____ (project/passive) unless _____ (the) _____ enabling _____ (condition) _____ (create/passive) alongside it — _____ (hardware) _____ alone _____ (not/sufficient/prove) without _____ (the) _____ institutional _____ capacity to _____ (operate) and _____ (maintain) it.','The / investment / will not generate / the / returns / projected / unless / the / enabling / conditions / are created / hardware / alone / will not prove sufficient / without / the / institutional / capacity / operate / maintain',NULL,'''Will not generate/prove sufficient'' in unless-conditional investment warning.','medium'),
  (cid,80,272,'gap_fill','If _____ (the) _____ right _____ institutional _____ (condition) _____ (put/passive) in _____ place now, _____ transition _____ (manage/passive) _____ successfully and _____ (deliver) _____ broadly _____ shared _____ gains — if _____ (not), _____ costs _____ (concentrate/passive) _____ in _____ communities _____ least _____ (equip/passive) to _____ bear _____ them.','the / right / institutional / conditions / are put / in place / the / transition / will be managed / successfully / will deliver / broadly / shared / if not / costs / will be concentrated / communities / least / equipped / bear',NULL,'''Will be managed/deliver/be concentrated'' in binary conditional for managed vs unmanaged transition.','hard'),
  (cid,80,273,'gap_fill','Should _____ (the) _____ evidence _____ (emerge) that _____ (the) _____ current _____ approach _____ (not/work), _____ (the) _____ responsible _____ course _____ (be) to _____ (acknowledge) _____ (this) _____ promptly and _____ (pivot) to _____ alternative _____ strategies rather than _____ (persist) with _____ (an) _____ approach _____ (not/prove).','the / evidence / emerge / the / current / approach / is not working / the / responsible / will be / to / acknowledge / this / promptly / pivot / to / alternative / strategies / persisting / an / approach / not proved',NULL,'''Should'' + ''will be'' for conditional epistemic responsibility.','hard'),
  (cid,80,274,'gap_fill','Unless _____ (the) _____ parties _____ (demonstrate) _____ (the) _____ political _____ will to _____ (compromise), _____ (the) _____ negotiations _____ (fail) and _____ (the) _____ opportunity _____ (present/passive) by _____ (this) _____ window _____ (close) — perhaps _____ permanently, _____ (as/similar) _____ windows have _____ in _____ (the) _____ past.','the / parties / demonstrate / the / political / will / compromise / the / negotiations / will fail / the / opportunity / presented / this / window / will close / as / similar / in / the / past',NULL,'''Will fail/close'' in unless-conditional negotiation warning.','medium'),
  (cid,80,275,'gap_fill','Provided _____ that _____ (the) _____ necessary _____ (condition) _____ (meet/passive), _____ (the) _____ initiative _____ (achieve) _____ (its) _____ goals and _____ (demonstrate) that _____ collaborative _____ approaches _____ (capable/be) of _____ (deliver) _____ outcomes that _____ neither _____ (party) _____ could _____ (achieve) _____ alone.','Provided / that / the / necessary / conditions / are met / the / initiative / will achieve / its / goals / demonstrate / collaborative / approaches / are capable / delivering / outcomes / neither / party / achieve / alone',NULL,'''Will achieve/demonstrate'' in ''provided that'' formal conditional.','medium'),
  (cid,80,276,'gap_fill','As long _____ as _____ (the) _____ fundamental _____ (structural) _____ imbalances _____ (remain) _____ unaddressed, _____ recurring _____ (crisis) _____ (continue) to _____ (emerge) regardless _____ of _____ (the) _____ quality _____ of _____ (the) _____ immediate _____ response _____ to _____ (them).','long / as / the / fundamental / structural / imbalances / remain / unaddressed / recurring / crises / will continue / emerge / regardless / the / quality / the / immediate / response / to / them',NULL,'''Will continue to emerge'' in ''as long as'' structural problem persistence warning.','medium'),
  (cid,80,277,'multiple_choice','Which conditional future construction MOST EFFECTIVELY warns about policy inaction?','Unless governments act now, the costs of addressing the problem in the future will far exceed what proactive action would cost today.','[''If governments act now, the costs will be lower.'',''Unless governments act now, the costs of addressing the problem in the future will far exceed what proactive action would cost today.'',''If governments had acted sooner, the costs would have been lower.'',''Unless governments acted, the costs would be higher.'']','''Unless governments act now...will far exceed'' = real conditional with concrete future cost comparison.','easy'),
  (cid,80,278,'gap_fill','If _____ these _____ (projection) _____ (prove) accurate — and there _____ (good/be) _____ reasons to _____ (think) they _____ (will) — _____ policymakers _____ (face) _____ (a) _____ set of _____ choices _____ that _____ (require) _____ (both) _____ technical _____ expertise and _____ political _____ courage.','these / projections / prove / there / are / good / reasons / think / they will / policymakers / will face / a / set / choices / will require / both / technical / expertise / political / courage',NULL,'''Will face/require'' in evidence-based conditional future policy challenge.','hard'),

  -- BLOCK 81: Gap fill avançado
  (cid,81,279,'gap_fill','_____ (the) _____ debate _____ (not/resolve) quickly or _____ (easily) — _____ (the) _____ evidence _____ (remain) _____ contested and _____ (the) _____ institutional _____ interests on _____ both _____ sides _____ (ensure) that _____ (the) _____ controversy _____ (persist) long _____ after _____ (the) _____ empirical _____ questions _____ (settle/passive).','The / debate / will not be resolved / quickly / easily / the / evidence / remains / contested / the / institutional / interests / will ensure / the / controversy / will persist / long / after / the / empirical / questions / have been settled',NULL,'''Will not be resolved/persist'' + ''will ensure'' for institutional interest in continued debate.','hard'),
  (cid,81,280,'gap_fill','What _____ (appear) today as _____ (an) _____ intractable _____ division _____ (prove) _____ manageable in _____ (the) _____ light of _____ future _____ (development) that _____ (we) _____ cannot _____ currently _____ (foresee) — _____ (a) _____ reminder that _____ (the) _____ present _____ (not/define) _____ (the) _____ possible.','appears / today / an / intractable / division / will prove / manageable / the / light / future / developments / we / foresee / a / reminder / the / present / does not define / the / possible',NULL,'''Will prove'' for future vindication of current optimism; PS ''appears/does not define.''','medium'),
  (cid,81,281,'gap_fill','_____ (the) _____ century _____ (belong) to _____ those who _____ (invest) now in _____ (the) _____ foundational _____ capabilities — _____ human _____ (capital), _____ infrastructure, _____ and _____ institutional _____ quality — that _____ (make) _____ sustained _____ prosperity _____ possible _____ in _____ (the) _____ long _____ run.','The / century / will belong / those / invest / the / foundational / capabilities / human / capital / infrastructure / institutional / quality / make / sustained / prosperity / possible / the / long / run',NULL,'''Will belong'' + PS ''invest/make'' for long-term investment in prosperity prediction.','hard'),
  (cid,81,282,'gap_fill','Progress _____ (not/linear) — _____ (there) _____ (be) _____ setbacks and _____ reversals, _____ moments when _____ (the) _____ forces of _____ regression _____ (temporarily/overwhelm) those of _____ (advancement). But _____ (the) _____ overall _____ trajectory, _____ (extend/passive) over _____ decades and _____ (century), _____ (bend) _____ toward _____ improvement.','will not be linear / there / will be / setbacks / reversals / moments / the / forces / regression / will temporarily overwhelm / advancement / the / overall / trajectory / extended / over / decades / centuries / will bend / toward / improvement',NULL,'''Will not be linear/will be/will temporarily overwhelm/will bend'' for long-arc progress argument.','hard'),
  (cid,81,283,'gap_fill','_____ (the/legacy) _____ of _____ (this/era) _____ (ultimately/determine/passive) not by _____ (the) _____ scale of _____ (the) _____ challenges _____ (face/passive) but by _____ (the) _____ quality of _____ (the) _____ responses _____ (make/passive) — _____ (whether) _____ (the) _____ institutions, _____ the _____ (leader) and _____ (the) _____ citizens of _____ today _____ (rise) to _____ (the) _____ moment.','The legacy / this era / will ultimately be determined / not / the / scale / the / challenges / faced / the / quality / the / responses / made / whether / the / institutions / leaders / the / citizens / today / rise / the / moment',NULL,'''Will be determined'' + ''whether...rise'' for legacy contingency argument.','hard'),
  (cid,81,284,'gap_fill','In _____ (the) _____ end, _____ what _____ (matter) _____ most _____ (be) not _____ (the) _____ predictions _____ we _____ (make) but _____ (the) _____ choices _____ we _____ (make) in _____ response to _____ them — _____ (and) _____ (the) _____ choices _____ we _____ (make) today _____ (shape) _____ tomorrow _____ in _____ ways that _____ (cannot) _____ be _____ (fully/anticipate/passive).','the / end / what / matters / most / is / not / the / predictions / we / make / the / choices / we / make / in / response / the / choices / we / make / today / will shape / tomorrow / ways / cannot / be / fully anticipated',NULL,'''Will shape'' + ''cannot be anticipated'' for human agency in future-making.','hard'),
  (cid,81,285,'gap_fill','_____ (the) _____ generation _____ entering _____ (the) _____ workforce _____ today _____ (spend) more _____ of _____ (their) _____ career _____ years _____ navigating _____ the _____ consequences of _____ (current) _____ decisions than _____ (those) _____ who _____ (make) them _____ (will) — _____ (a) _____ fact that _____ (rarely/give) _____ those most _____ (affect/passive) _____ adequate _____ voice in _____ present _____ debates.','The / generation / entering / the / workforce / today / will spend / more / of / their / career / years / navigating / consequences / current / decisions / those / who / make / them / will / a / fact / is rarely given / those / most / affected / adequate / voice / present / debates',NULL,'''Will spend/rarely gives'' for intergenerational decision consequence burden argument.','hard'),
  (cid,81,286,'gap_fill','If _____ (the) _____ analysis _____ in _____ (this) _____ essay _____ (correct/prove), _____ (the) _____ implications _____ (profound/be): _____ (the) _____ conventional _____ approaches _____ (not/adequate/prove) and _____ (a) _____ more _____ fundamental _____ rethinking _____ (require/passive).','the / analysis / in / this / essay / proves correct / the / implications / will be profound / the / conventional / approaches / will not prove adequate / a / more / fundamental / rethinking / will be required',NULL,'''Proves correct/will be/will not prove/will be required'' for conditional essay implication.','hard'),

  -- BLOCK 82: Exercícios finais de produção
  (cid,82,287,'production','[TOEFL Writing — 200 words] Write a conclusion predicting what will happen over the next generation on a major global issue.','',NULL,'The next generation will inherit a world shaped by the decisions made in the current period, and the evidence suggests that those decisions are pointing in contradictory directions. On climate, the evidence indicates that temperatures will continue to rise and that the most severe impacts will fall on the most vulnerable populations unless the pace of decarbonization accelerates substantially — and current trajectories suggest it will not do so fast enough to avoid significant warming. On economic inequality, the evidence suggests that the gains from technological change will continue to accrue disproportionately to those with capital and high-level skills unless policy actively redistributes them — and the political conditions for doing so are uncertain at best. On democratic governance, the picture is equally mixed: democratic systems will face continued stress from information environment disruption and populist mobilization, but they will also generate the civil society responses needed to defend themselves. The overall picture is not one of inevitable progress or inevitable decline but of genuine contingency — of a future that will be shaped by choices not yet made by actors not yet fully determined. What the next generation will inherit depends not only on what we do now but on what it chooses to do with what it inherits. And that, ultimately, is a source of both responsibility and hope.','hard'),
  (cid,82,288,'production','[TOEFL Speaking — 60s] The reading predicts certain economic outcomes over the next decade. The professor agrees with some predictions but challenges others. Summarize.','',NULL,'The reading makes several predictions about economic outcomes over the next decade, some of which the professor agrees with and some of which she challenges. The reading predicts that technological automation will continue to displace workers in manufacturing and routine service occupations, and the professor agrees that this will occur. However, the reading predicts that new jobs will emerge in sufficient numbers to compensate for those lost, and the professor challenges this prediction vigorously. She argues that the evidence from previous rounds of technological disruption does not straightforwardly support optimism about job creation, because the new jobs that will emerge will tend to require higher skills than the jobs lost, will tend to be located in different geographical areas, and will tend to emerge on different timescales than the displacement. The reading predicts that inequality will stabilize as labor market institutions adapt, and the professor challenges this too, arguing that without active policy intervention — significantly stronger labor market regulation, redistributive taxation, and investment in education and retraining — inequality will continue to widen. The one prediction where the professor largely agrees is that global trade will remain significant even as geopolitical tensions rise, because the economic interdependencies created by decades of globalization will prove difficult to unwind quickly, though she notes that the composition and geography of trade will change substantially.','hard'),
  (cid,82,289,'gap_fill','[TOEFL Writing] The evidence _____ (point) to _____ (a) _____ future that _____ (neither/straightforwardly) _____ (hopeful/be) nor _____ straightforwardly _____ bleak — one in which _____ (the) _____ outcome _____ (depend) on _____ (the) _____ choices _____ (make/passive) now and _____ in _____ (the) _____ years _____ immediately _____ ahead.','points / to / a / future / will be neither straightforwardly / hopeful / nor / straightforwardly / the / outcome / will depend / the / choices / made / now / the / years / immediately / ahead',NULL,'''Will be/depend'' for open future argument; PS ''points'' for current evidence claim.','medium'),
  (cid,82,290,'gap_fill','[TOEFL Writing] _____ (we) _____ (know) with _____ certainty _____ what _____ (the) _____ future _____ (hold) — _____ (there/always/be) _____ (unforeseen) _____ developments, _____ disruptive _____ (technology), and _____ unexpected _____ (turn) of _____ events. _____ (what) _____ (we/know) is _____ that _____ (the) _____ choices _____ we _____ (make) _____ now _____ (set) _____ (the) _____ conditions for _____ (the) _____ future _____ (that/unfold).','We / will never know / with / certainty / what / the / future / holds / there / will always be / unforeseen / developments / disruptive / technologies / unexpected / turns / events / What / we do know / is / that / the / choices / we / make / now / will set / the / conditions / the / future / that / unfolds',NULL,'''Will never know/will always be/will set'' + PS ''holds/we make/unfolds'' for epistemic humility about future.','hard'),
  (cid,82,291,'gap_fill','[TOEFL Writing] It _____ (take) _____ more _____ than _____ good _____ intentions to _____ (address) _____ challenges of _____ (this) _____ scale — _____ (it) _____ (require) _____ (the) _____ institutional _____ capacity, _____ (the) _____ political _____ will, and _____ (the) _____ sustained _____ commitment _____ over _____ time _____ that _____ (only/generate) when _____ (the) _____ public _____ (understand) _____ and _____ (support) _____ what _____ (need) to _____ be _____ done.','will take / more / than / good / intentions / address / challenges / this / scale / it / will require / the / institutional / capacity / the / political / will / the / sustained / commitment / over / time / are only generated / the / public / understands / and / supports / needs',NULL,'''Will take/require'' + ''are only generated'' for institutional capacity argument.','hard'),
  (cid,82,292,'gap_fill','In _____ (the) _____ final _____ analysis, _____ (the) _____ future _____ (not/give) to _____ (us) — _____ (it) _____ (make/passive) by _____ (us), through _____ (the) _____ cumulative _____ effect of _____ (count) _____ individual and _____ institutional _____ decisions that _____ (add up) to _____ (the) _____ trajectory we _____ (ultimately/travel).','the / final / analysis / the / future / will not be given / to / us / it / will be made / by / us / through / the / cumulative / effect / countless / individual / institutional / decisions / add up / the / trajectory / we / ultimately travel',NULL,'''Will be given/will be made'' passive for human agency in future-making conclusion.','medium'),
  (cid,82,293,'production','[TOEFL Writing — 200 words] Write a final synthesis paragraph on what the future will hold for international institutions.','',NULL,'The future of international institutions will be determined by whether the major powers that created them and that currently sustain them can be persuaded that the costs of effective multilateralism are worth paying relative to the alternatives. That case is not easy to make in the current political environment, where the short-term costs of international commitments are visible and politically salient while the long-term benefits are diffuse and often taken for granted. But the case is there to be made, and the stakes of getting it wrong are high. International institutions will either adapt to a changed world — reforming their governance to reflect the current distribution of global power, expanding their mandates to address challenges that their founders could not have foreseen, and developing new models of engagement with the non-state actors whose resources and capabilities are increasingly necessary — or they will gradually lose the relevance and legitimacy that allow them to perform their functions. If they adapt, they will continue to provide the global public goods that no other mechanism can efficiently produce: the rules that enable commerce, the frameworks that constrain conflict, the standards that protect health and environment, the forums in which disputes can be managed through negotiation rather than coercion. If they do not, the vacuum will not remain empty — it will be filled by arrangements that will likely prove less equitable, less predictable, and less capable of managing the interdependencies that a deeply connected world will continue to generate.','hard'},
  (cid,82,294,'production','[TOEFL Writing — Final capstone 200 words] Write a final concluding paragraph on what the analysis predicts about the next century.','',NULL,'What the analysis undertaken in this essay predicts about the next century is not a single trajectory but a range of possible futures, the realization of which will depend on choices that have not yet been made. The most optimistic scenario — in which effective climate action limits warming to manageable levels, in which the gains from technological change are broadly shared through adequate policy, in which international institutions adapt to a changed world and continue to provide global public goods, and in which democratic governance proves resilient enough to manage the pressures upon it — is genuinely achievable, but only if the conditions for achieving it are actively built rather than assumed. The most pessimistic scenario — in which climate change proceeds unchecked toward catastrophic outcomes, in which rising inequality and technological disruption fuel political instability, in which great power competition prevents the cooperation needed to address shared challenges, and in which democratic erosion proves irreversible — is also genuinely possible, though its realization will reflect failures of choice rather than failures of capability. Between these poles lies a wide range of intermediate outcomes, each reflecting a particular combination of successes and failures in addressing the challenges this analysis has identified. The century will not be made for us; it will be made by us, through the choices that individuals, institutions, and governments will make, year by year, in response to the circumstances they will encounter. That is the enduring truth about the future: it will belong to those who shape it.','hard')

